"use client";

import { useCallback, useState } from 'react';
import { useDropzone, type Accept } from 'react-dropzone';
import { Upload, FileText, Image, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import { useI18n } from '@/lib/i18n';

interface FileUploadAreaProps {
  acceptedTypes: 'documents' | 'images';
  onFileSelect: (file: File | null) => void;
  selectedFile: File | null;
}

export function FileUploadArea({ acceptedTypes, onFileSelect, selectedFile }: FileUploadAreaProps) {
  const { t } = useI18n();
  const [isDragOver, setIsDragOver] = useState(false);

    const getAcceptedFormats = useCallback((): Accept => {
    if (acceptedTypes === 'documents') {
      return {
        'application/pdf': ['.pdf'],
        'application/msword': ['.doc'],
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document': ['.docx'],
        'text/plain': ['.txt'],
      };
    } else {
      return {
        'image/jpeg': ['.jpeg', '.jpg'],
        'image/png': ['.png'],
        'image/webp': ['.webp'],
        'image/gif': ['.gif'],
      };
    }
  }, [acceptedTypes]);

  const onDrop = useCallback((acceptedFiles: File[]) => {
    if (acceptedFiles.length > 0) {
      onFileSelect(acceptedFiles[0]);
    }
    setIsDragOver(false);
  }, [onFileSelect]);

  const acceptedFormats = getAcceptedFormats();

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: acceptedFormats,
    multiple: false,
    onDragEnter: () => setIsDragOver(true),
    onDragLeave: () => setIsDragOver(false),
  });

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const getSupportedFormats = () => {
    if (acceptedTypes === 'documents') {
      return 'PDF, DOC, DOCX, TXT';
    } else {
      return 'JPG, PNG, WEBP, GIF';
    }
  };

  const removeFile = (e: React.MouseEvent) => {
    e.stopPropagation();
    onFileSelect(null);
  };

  return (
    <div className="w-full">
      <div
        {...getRootProps()}
        className={cn(
          "border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-colors",
          isDragActive || isDragOver
            ? "border-blue-500 bg-blue-50"
            : "border-gray-300 hover:border-gray-400",
          selectedFile && "border-green-500 bg-green-50"
        )}
      >
        <input {...getInputProps()} />

        {selectedFile ? (
          <div className="space-y-4">
            <div className="flex items-center justify-center">
              {acceptedTypes === 'documents' ? (
                <FileText className="w-12 h-12 text-green-600" />
              ) : (
                <Image className="w-12 h-12 text-green-600" />
              )}
            </div>
            <div className="space-y-2">
              <p className="font-medium text-gray-900">{selectedFile.name}</p>
              <p className="text-sm text-gray-500">{formatFileSize(selectedFile.size)}</p>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={removeFile}
              className="mt-2"
            >
              <X className="w-4 h-4 mr-2" />
              {t.removeFile}
            </Button>
          </div>
        ) : (
          <div className="space-y-4">
            <div className="flex items-center justify-center">
              <Upload className="w-12 h-12 text-gray-400" />
            </div>
            <div className="space-y-2">
              <p className="text-lg font-medium text-gray-900">
                {isDragActive ? 'Drop your file here' : (acceptedTypes === 'documents' ? t.uploadDocument : t.uploadImage)}
              </p>
              <p className="text-sm text-gray-500">
                {t.dragAndDrop}
              </p>
              <p className="text-xs text-gray-400">
                {t.supportsFormats}: {getSupportedFormats()}
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { FileUploadArea } from './FileUploadArea';
import { LanguageDropdown } from './LanguageDropdown';
import { LanguageSelector } from './LanguageSelector';
import { ApiKeyInput } from './ApiKeyInput';
import { TranslationProgress } from './TranslationProgress';
import { DocumentViewer } from './DocumentViewer';
import { JobHistory } from './JobHistory';
import { FileText, Image, Settings, ArrowRight } from 'lucide-react';
import { useI18n } from '@/lib/i18n';
import { supabase } from '@/lib/supabase';
import { SignInPrompt } from './TranslationScreen/SignInPrompt';
import { LanguageSelectionPanel } from './TranslationScreen/LanguageSelectionPanel';
import { useAuth, useApiKey } from './TranslationScreen/hooks';
import { apiClient, handleError, downloadTranslatedFile } from './TranslationScreen/utils';
import type { Asset, Job } from './TranslationScreen/types';

export function TranslationScreen() {
  const { t } = useI18n();
  const { user } = useAuth();
  const { apiKey, setApiKey, saveApiKey } = useApiKey();

  const [activeTab, setActiveTab] = useState<'documents' | 'images'>('documents');
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [sourceLanguage, setSourceLanguage] = useState<string>('auto');
  const [targetLanguage, setTargetLanguage] = useState<string>('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [showApiKeyInput, setShowApiKeyInput] = useState(false);
  const [translatedFile, setTranslatedFile] = useState<File | null>(null);
  const [uploadedAsset, setUploadedAsset] = useState<Asset | null>(null);
  const [currentJob, setCurrentJob] = useState<Job | null>(null);
  const [error, setError] = useState<string | null>(null);


  const handleFileUpload = async (file: File | null) => {
    if (!file || !user) {
      resetFileSelection();
      return;
    }

    setError(null);
    setIsProcessing(true);

    try {
      const data = await apiClient.upload(file);
      setUploadedAsset(data.asset);
      setSelectedFile(file);
    } catch (err) {
      setError(handleError(err));
    } finally {
      setIsProcessing(false);
    }
  };

  const resetFileSelection = () => {
    setSelectedFile(null);
    setUploadedAsset(null);
  };

  const handleTranslate = async () => {
    if (!canTranslate()) return;

    setError(null);
    setIsProcessing(true);

    try {
      const data = await apiClient.createJob(uploadedAsset!.id, targetLanguage, sourceLanguage);
      setCurrentJob(data.job);
    } catch (err) {
      setError(handleError(err));
      setIsProcessing(false);
    }
  };

  const canTranslate = () => {
    return uploadedAsset && targetLanguage && sourceLanguage !== targetLanguage && user;
  };

  // Monitor job status updates
  useEffect(() => {
    if (!currentJob?.id) return;

    const channel = supabase
      .channel(`jobs:${currentJob.id}`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'jobs',
          filter: `id=eq.${currentJob.id}`,
        },
        (payload) => {
          setCurrentJob(payload.new as Job);
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [currentJob?.id]);

  // Handle job completion
  useEffect(() => {
    const handleJobCompleted = async () => {
      if (!currentJob?.translated_asset?.url) return;

      try {
        const fileName = currentJob.translated_asset.url.split('/').pop() || 'translated-file';
        const file = await downloadTranslatedFile(currentJob.translated_asset.url, fileName);
        setTranslatedFile(file);
      } catch (err) {
        setError('Failed to load translated file.');
      }
    };

    if (!currentJob) return;

    if (currentJob.status === 'completed') {
      setIsProcessing(false);
      handleJobCompleted();
    } else if (currentJob.status === 'failed') {
      setIsProcessing(false);
      setError(currentJob.error_message || 'Translation failed');
    }
  }, [currentJob]);

  const handleApiKeySave = () => {
    saveApiKey();
    setShowApiKeyInput(false);
  };

  if (!user) {
    return <SignInPrompt error={error} />;
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Top Bar */}
      <header className="bg-white border-b border-gray-200 px-6 py-4">
        <div className="flex justify-between items-center max-w-7xl mx-auto">
          <div className="flex items-center space-x-4">
            <h1 className="text-2xl font-bold text-gray-900">{t.visualTranslator}</h1>
          </div>
          <div className="flex items-center space-x-4">
            <LanguageSelector />
            <Button
              variant="outline"
              size="sm"
              onClick={() => setShowApiKeyInput(true)}
              className="flex items-center space-x-2"
            >
              <Settings className="w-4 h-4" />
              <span>{t.addApiKey}</span>
            </Button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-6 py-8">
        <div className="mb-8 text-center">
          <h1 className="text-4xl font-bold text-gray-900 mb-4">
            {t.documentTranslation}
          </h1>
          <p className="text-lg text-gray-600 max-w-2xl mx-auto">
            {t.preserveFormatting}
          </p>
        </div>

        <Card className="max-w-6xl mx-auto">
          <CardHeader>
            <Tabs value={activeTab} onValueChange={(value) => setActiveTab(value as 'documents' | 'images')}>
              <TabsList className="grid w-full grid-cols-2">
                <TabsTrigger value="documents" className="flex items-center space-x-2">
                  <FileText className="w-4 h-4" />
                  <span>{t.documentsTab}</span>
                </TabsTrigger>
                <TabsTrigger value="images" className="flex items-center space-x-2">
                  <Image className="w-4 h-4" />
                  <span>{t.imagesTab}</span>
                </TabsTrigger>
              </TabsList>
            </Tabs>
          </CardHeader>

          <CardContent className="p-6">
            <Tabs value={activeTab}>
              <TabsContent value="documents" className="mt-0">
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                  {/* Left Side - File Upload */}
                  <div>
                    <FileUploadArea
                      acceptedTypes={activeTab === 'documents' ? 'documents' : 'images'}
                      onFileSelect={handleFileUpload}
                      selectedFile={selectedFile}
                    />
                  </div>

                  <LanguageSelectionPanel
                    sourceLanguage={sourceLanguage}
                    targetLanguage={targetLanguage}
                    onSourceLanguageChange={setSourceLanguage}
                    onTargetLanguageChange={setTargetLanguage}
                    onTranslate={handleTranslate}
                    canTranslate={canTranslate()}
                    isProcessing={isProcessing}
                    apiKey={apiKey}
                    tabType="documents"
                  />
                </div>
              </TabsContent>

              <TabsContent value="images" className="mt-0">
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                  {/* Left Side - File Upload */}
                  <div>
                    <FileUploadArea
                      acceptedTypes="images"
                      onFileSelect={handleFileUpload}
                      selectedFile={selectedFile}
                    />
                  </div>

                  <LanguageSelectionPanel
                    sourceLanguage={sourceLanguage}
                    targetLanguage={targetLanguage}
                    onSourceLanguageChange={setSourceLanguage}
                    onTargetLanguageChange={setTargetLanguage}
                    onTranslate={handleTranslate}
                    canTranslate={canTranslate()}
                    isProcessing={isProcessing}
                    apiKey={apiKey}
                    tabType="images"
                  />
                </div>
              </TabsContent>
            </Tabs>

            {/* Translation Progress */}
            {isProcessing && (
              <div className="mt-8">
                <TranslationProgress
                  isProcessing={isProcessing}
                  onComplete={() => setIsProcessing(false)}
                />
              </div>
            )}

            {/* Document Viewer */}
            {(selectedFile || translatedFile) && !isProcessing && (
              <div className="mt-8">
                <DocumentViewer
                  originalFile={selectedFile}
                  translatedFile={translatedFile}
                  targetLanguage={targetLanguage}
                />
              </div>
            )}
          </CardContent>
        </Card>

        <div className="mt-8">
          <JobHistory />
        </div>
      </main>

      {/* API Key Input Modal */}
      {showApiKeyInput && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-md w-full mx-4">
            <ApiKeyInput
              apiKey={apiKey}
              setApiKey={setApiKey}
              onSave={handleApiKeySave}
            />
          </div>
        </div>
      )}
    </div>
  );
}

import { NextRequest, NextResponse } from 'next/server'
import { createClient, type SupabaseClient } from '@supabase/supabase-js'
import { z } from 'zod'
import { RateLimiter, rateLimiters, withAdvancedRateLimit } from './rate-limiter'

// Enhanced types for better DX
export interface AuthenticatedUser {
  id: string
  email?: string
  app_metadata?: Record<string, any>
  user_metadata?: Record<string, any>
}

export interface AuthenticatedRequest extends NextRequest {
  user: AuthenticatedUser
  supabase: SupabaseClient
}

// Standard API response types
export interface ApiResponse<T = any> {
  data?: T
  error?: string
  code?: string
  details?: any
  message?: string
}

// Handler type definitions for better type inference
export type ApiHandler<T = any> = (
  req: AuthenticatedRequest
) => Promise<NextResponse<ApiResponse<T>>>

export type ValidatedApiHandler<TSchema, TResponse = any> = (
  req: AuthenticatedRequest,
  data: TSchema
) => Promise<NextResponse<ApiResponse<TResponse>>>

// Environment validation
const envSchema = z.object({
  NEXT_PUBLIC_SUPABASE_URL: z.string().url(),
  NEXT_PUBLIC_SUPABASE_ANON_KEY: z.string().min(1),
  NEXT_PUBLIC_APP_URL: z.string().url().optional(),
  SUPABASE_SERVICE_ROLE_KEY: z.string().min(1).optional(),
})

// Validate environment variables
const env = envSchema.safeParse(process.env)
if (!env.success) {
  console.warn('⚠️ Environment validation warnings:', env.error.errors)
}

// Create Supabase client for server-side operations
function createServerSupabase(token?: string) {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://placeholder.supabase.co'
  const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || 'placeholder-key'

  const client = createClient(supabaseUrl, supabaseKey, {
    auth: {
      autoRefreshToken: false,
      persistSession: false,
    },
    global: {
      headers: token ? { Authorization: `Bearer ${token}` } : {},
    },
  })

  return client
}

// Enhanced error responses with proper typing and better DX
export class ApiError extends Error {
  constructor(
    public statusCode: number,
    message: string,
    public code?: string,
    public details?: any
  ) {
    super(message)
    this.name = 'ApiError'
  }

  // Helper methods for common error types
  static badRequest(message: string, details?: any) {
    return new ApiError(400, message, 'BAD_REQUEST', details)
  }

  static unauthorized(message = 'Unauthorized', details?: any) {
    return new ApiError(401, message, 'UNAUTHORIZED', details)
  }

  static forbidden(message = 'Forbidden', details?: any) {
    return new ApiError(403, message, 'FORBIDDEN', details)
  }

  static notFound(message = 'Not found', details?: any) {
    return new ApiError(404, message, 'NOT_FOUND', details)
  }

  static validation(message = 'Validation failed', details?: any) {
    return new ApiError(400, message, 'VALIDATION_ERROR', details)
  }

  static internal(message = 'Internal server error', details?: any) {
    return new ApiError(500, message, 'INTERNAL_ERROR', details)
  }

  static rateLimit(message = 'Too many requests', details?: any) {
    return new ApiError(429, message, 'RATE_LIMIT_EXCEEDED', details)
  }
}

// Helper function to create standardized API responses
export function createApiResponse<T>(
  data?: T,
  message?: string,
  status = 200
): NextResponse<ApiResponse<T>> {
  return NextResponse.json({ data, message }, { status })
}

export function createErrorResponse(
  error: string | ApiError,
  status?: number
): NextResponse<ApiResponse> {
  if (typeof error === 'string') {
    return NextResponse.json(
      { error, code: 'ERROR' },
      { status: status || 500 }
    )
  }

  return NextResponse.json(
    {
      error: error.message,
      code: error.code,
      details: error.details
    },
    { status: error.statusCode }
  )
}

// Security headers middleware
export function addSecurityHeaders(response: NextResponse): NextResponse {
  // OWASP recommended security headers
  response.headers.set('X-Content-Type-Options', 'nosniff')
  response.headers.set('X-Frame-Options', 'DENY')
  response.headers.set('X-XSS-Protection', '1; mode=block')
  response.headers.set('Referrer-Policy', 'strict-origin-when-cross-origin')
  response.headers.set('Permissions-Policy', 'camera=(), microphone=(), geolocation=()')

  // CORS headers for our domain
  response.headers.set('Access-Control-Allow-Origin', process.env.NEXT_PUBLIC_APP_URL || '*')
  response.headers.set('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS')
  response.headers.set('Access-Control-Allow-Headers', 'Content-Type, Authorization')

  return response
}

// Enhanced JWT Authentication Middleware with better error handling
export function withAuth<T = any>(
  handler: ApiHandler<T>
) {
  return async (request: NextRequest): Promise<NextResponse<ApiResponse<T>>> => {
    try {
      // Extract JWT token from Authorization header
      const authHeader = request.headers.get('authorization')
      const token = authHeader?.replace('Bearer ', '')

      if (!token) {
        // For development, allow requests without tokens for testing
        if (process.env.NODE_ENV === 'development') {
          console.warn('⚠️  Development mode: Skipping auth for testing')
          const mockUser: AuthenticatedUser = {
            id: 'dev-user-id',
            email: 'dev@example.com'
          }
          const supabase = createServerSupabase()
          Object.assign(request, { user: mockUser, supabase })
          return handler(request as AuthenticatedRequest)
        }

        throw ApiError.unauthorized('Missing authorization token')
      }

      // Create Supabase client with the user's token
      const supabase = createServerSupabase(token)

      // Verify the JWT and get user information
      const { data: { user }, error } = await supabase.auth.getUser(token)

      if (error || !user) {
        throw ApiError.unauthorized('Invalid or expired token', error)
      }

      // Add user and supabase client to request with proper typing
      Object.assign(request, { user, supabase })

      // Call the protected handler
      const response = await handler(request as AuthenticatedRequest)

      // Add security headers to response
      return addSecurityHeaders(response) as NextResponse<ApiResponse<T>>

    } catch (error) {
      console.error('🚫 Auth middleware error:', error)
      return createErrorResponse(error instanceof ApiError ? error : ApiError.unauthorized())
    }
  }
}

// Enhanced Zod Validation Middleware with better type inference
export function withValidation<TSchema, TResponse = any>(
  schema: z.ZodSchema<TSchema>
) {
  return function(
    handler: ValidatedApiHandler<TSchema, TResponse>
  ) {
    return async (request: AuthenticatedRequest): Promise<NextResponse<ApiResponse<TResponse>>> => {
      try {
        let rawData: any

        // Parse request data based on content type and method
        const contentType = request.headers.get('content-type')
        const method = request.method.toLowerCase()

        if (method === 'get' || method === 'delete') {
          // For GET/DELETE requests, use query parameters
          const url = new URL(request.url)
          rawData = Object.fromEntries(url.searchParams.entries())

          // Convert string values to appropriate types for common fields
          Object.keys(rawData).forEach(key => {
            const value = rawData[key]
            if (value === 'true' || value === 'false') {
              rawData[key] = value === 'true'
            } else if (!isNaN(Number(value)) && value !== '') {
              rawData[key] = Number(value)
            }
          })
        } else if (contentType?.includes('application/json')) {
          try {
            rawData = await request.json()
          } catch {
            throw ApiError.badRequest('Invalid JSON payload')
          }
        } else if (contentType?.includes('multipart/form-data')) {
          const formData = await request.formData()
          rawData = Object.fromEntries(formData.entries())
        } else if (contentType?.includes('application/x-www-form-urlencoded')) {
          const formData = await request.formData()
          rawData = Object.fromEntries(formData.entries())
        } else {
          rawData = {}
        }

        // Validate the data with Zod
        const validation = schema.safeParse(rawData)

        if (!validation.success) {
          const errorDetails = validation.error.errors.map(err => ({
            field: err.path.join('.'),
            message: err.message,
            code: err.code
          }))

          throw ApiError.validation('Request validation failed', errorDetails)
        }

        // Call handler with validated data
        return await handler(request, validation.data)

      } catch (error) {
        console.error('🔍 Validation middleware error:', error)
        return createErrorResponse(
          error instanceof ApiError ? error : ApiError.badRequest('Request validation failed')
        )
      }
    }
  }
}

// Enhanced Logging Middleware with structured logging
interface RequestContext {
  requestId: string
  method: string
  url: string
  userAgent: string
  userId: string
  startTime: number
}

export function withLogging<T>(
  handler: ApiHandler<T>
) {
  return async (request: AuthenticatedRequest): Promise<NextResponse<ApiResponse<T>>> => {
    const requestId = crypto.randomUUID().slice(0, 8)
    const startTime = Date.now()
    const method = request.method
    const url = new URL(request.url)
    const pathname = url.pathname
    const userAgent = request.headers.get('user-agent') || 'unknown'
    const userId = request.user?.id || 'anonymous'

    const context: RequestContext = {
      requestId,
      method,
      url: pathname,
      userAgent,
      userId,
      startTime
    }

    // Enhanced request logging
    console.log(`🚀 [${requestId}] ${method} ${pathname}`, {
      user: userId,
      userAgent: userAgent.slice(0, 100),
      timestamp: new Date().toISOString()
    })

    try {
      const response = await handler(request)
      const duration = Date.now() - startTime
      const status = response.status

      // Success logging with performance metrics
      const logLevel = status >= 400 ? '⚠️' : status >= 500 ? '❌' : '✅'
      console.log(`${logLevel} [${requestId}] ${method} ${pathname} - ${status} (${duration}ms)`, {
        user: userId,
        duration,
        status,
        timestamp: new Date().toISOString()
      })

      // Add request context to response headers for debugging
      if (process.env.NODE_ENV === 'development') {
        response.headers.set('X-Request-ID', requestId)
        response.headers.set('X-Response-Time', `${duration}ms`)
      }

      return response
    } catch (error) {
      const duration = Date.now() - startTime
      console.error(`💥 [${requestId}] ${method} ${pathname} - ERROR (${duration}ms)`, {
        user: userId,
        duration,
        error: error instanceof Error ? error.message : String(error),
        stack: error instanceof Error ? error.stack : undefined,
        timestamp: new Date().toISOString()
      })

      throw error
    }
  }
}

// Enhanced middleware composition with better type safety
type MiddlewareFunction = (handler: any) => any

export function withMiddleware(
  ...middlewares: MiddlewareFunction[]
) {
  return function<T>(handler: T): T {
    return middlewares.reduceRight((acc, middleware) => middleware(acc), handler) as T
  }
}

// Helper to get a unique identifier for rate limiting
const getRateLimitIdentifier = (req: NextRequest | AuthenticatedRequest): string => {
  const authReq = req as AuthenticatedRequest
  return authReq.user?.id || req.headers.get('x-forwarded-for') || req.headers.get('x-real-ip') || 'unknown'
}

// Enhanced commonly used middleware combinations with better DX
export function withSecureApi<T = any>(
  limiter: RateLimiter = rateLimiters.api
) {
  return (handler: ApiHandler<T>) => {
    return withMiddleware(
      withAuth,
      withAdvancedRateLimit(limiter, getRateLimitIdentifier),
      withLogging
    )(handler)
  }
}

export function withSecureValidatedApi<TSchema, TResponse = any>(
  schema: z.ZodSchema<TSchema>,
  limiter: RateLimiter = rateLimiters.api
) {
  return (handler: ValidatedApiHandler<TSchema, TResponse>) => {
    return withMiddleware(
      withAuth,
      withAdvancedRateLimit(limiter, getRateLimitIdentifier),
      withValidation(schema),
      withLogging
    )(handler)
  }
}

// Convenience functions for common patterns
export function createApiEndpoint<T = any>(
  handler: ApiHandler<T>,
  options: {
    rateLimit?: RateLimiter
    skipAuth?: boolean
  } = {}
) {
  const { rateLimit = rateLimiters.api, skipAuth = false } = options

  if (skipAuth) {
    return withMiddleware(withLogging)(handler)
  }

  return withSecureApi<T>(rateLimit)(handler)
}

export function createValidatedApiEndpoint<TSchema, TResponse = any>(
  schema: z.ZodSchema<TSchema>,
  handler: ValidatedApiHandler<TSchema, TResponse>,
  options: {
    rateLimit?: RateLimiter
    skipAuth?: boolean
  } = {}
) {
  const { rateLimit = rateLimiters.api, skipAuth = false } = options

  if (skipAuth) {
    return withMiddleware(
      withValidation(schema),
      withLogging
    )(handler)
  }

  return withSecureValidatedApi<TSchema, TResponse>(schema, rateLimit)(handler)
}

