interface I18nContextType {
  language: string;
  setLanguage: (lang: string) => void;
  t: Translations;
  detectAndSetLanguage: () => void;
}

const I18nContext = createContext<I18nContextType | undefined>(undefined);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState('en');

  // Validate and set language with Zod schema
  const setValidatedLanguage = (lang: string) => {
    const validation = validateUILanguage(lang);
    if (validation.success) {
      setLanguage(validation.data);
      localStorage.setItem('ui-language', validation.data);
    } else {
      console.warn(`Invalid UI language: ${lang}, falling back to English`);
      setLanguage('en');
    }
  };

  const detectAndSetLanguage = async () => {
    try {
      // Try to get user's location and detect language based on region
      if ('geolocation' in navigator) {
        navigator.geolocation.getCurrentPosition(
          async (position) => {
            try {
              // Use a geolocation API to get country from coordinates
              const response = await fetch(
                `https://api.bigdatacloud.net/data/reverse-geocode-client?latitude=${position.coords.latitude}&longitude=${position.coords.longitude}&localityLanguage=en`
              );
              const data = await response.json();

              // Map countries to languages
              const countryToLanguage: Record<string, string> = {
                'Spain': 'es',
                'Mexico': 'es',
                'Argentina': 'es',
                'Colombia': 'es',
                'France': 'fr',
                'Germany': 'de',
                'Austria': 'de',
                'Switzerland': 'de',
                // Add more mappings as needed
              };

              const detectedLanguage = countryToLanguage[data.countryName] || 'en';
              setLanguage(detectedLanguage);
              localStorage.setItem('preferred-language', detectedLanguage);
            } catch (error) {
              console.warn('Failed to detect language from location:', error);
              fallbackToNavigatorLanguage();
            }
          },
          () => {
            // Geolocation failed, fallback to navigator language
            fallbackToNavigatorLanguage();
          }
        );
      } else {
        fallbackToNavigatorLanguage();
      }
    } catch (error) {
      console.warn('Language detection failed:', error);
      fallbackToNavigatorLanguage();
    }
  };

  const fallbackToNavigatorLanguage = () => {
    // Fallback to browser language
    const browserLang = navigator.language?.split('-')[0] || 'en';
    const validation = validateUILanguage(browserLang);
    const supportedLanguage = validation.success && translations[validation.data] ? validation.data : 'en';
    setValidatedLanguage(supportedLanguage);
  };

  useEffect(() => {
    // Check for saved language preference first
    const savedLanguage = localStorage.getItem('preferred-language');
    if (savedLanguage) {
      const validation = validateUILanguage(savedLanguage);
      if (validation.success && translations[validation.data]) {
        setLanguage(validation.data);
      } else {
        detectAndSetLanguage();
      }
    } else {
      detectAndSetLanguage();
    }
  }, []);

  // Validate translations on build
  useEffect(() => {
    Object.entries(translations).forEach(([lang, trans]) => {
      const validation = validateTranslations(trans);
      if (!validation.success) {
        console.warn(`Translation validation failed for ${lang}:`, validation.error.errors);
      }
    });
  }, []);

  const contextValue: I18nContextType = {
    language,
    setLanguage: setValidatedLanguage,
    t: translations[language] || translations.en,
    detectAndSetLanguage,
  };

  return (
    <I18nContext.Provider value={contextValue}>
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (context === undefined) {
    throw new Error('useI18n must be used within an I18nProvider');
  }
  return context;
}

import { z } from 'zod';
import DOMPurify from 'isomorphic-dompurify';

// Comprehensive input validation and sanitization
export class InputSanitizer {

  // Sanitize text content to prevent XSS
  static sanitizeText(input: string): string {
    if (typeof input !== 'string') {
      throw new Error('Input must be a string');
    }

    // Remove null bytes and control characters
    const cleaned = input.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');

    // Use DOMPurify for XSS prevention
    return DOMPurify.sanitize(cleaned, {
      ALLOWED_TAGS: [],
      ALLOWED_ATTR: [],
      KEEP_CONTENT: true
    });
  }

  // Validate and sanitize language codes
  static validateLanguageCode(code: string): string {
    const languageSchema = z.string()
      .min(2)
      .max(10)
      .regex(/^[a-z]{2,3}(-[A-Z]{2})?$|^auto$/);

    const validation = languageSchema.safeParse(code);
    if (!validation.success) {
      throw new Error('Invalid language code format');
    }

    return validation.data;
  }

  // Validate file names and prevent directory traversal
  static validateFileName(fileName: string): string {
    if (typeof fileName !== 'string') {
      throw new Error('File name must be a string');
    }

    // Remove dangerous characters and path traversal attempts
    const sanitized = fileName
      .replace(/[<>:"/\\|?*\x00-\x1f]/g, '')
      .replace(/\.\./g, '')
      .replace(/^\.+/, '')
      .trim();

    if (sanitized.length === 0) {
      throw new Error('Invalid file name');
    }

    if (sanitized.length > 255) {
      throw new Error('File name too long');
    }

    return sanitized;
  }

  // Validate MIME types against allowlist
  static validateMimeType(mimeType: string, allowedTypes: string[]): string {
    const mimeSchema = z.string().regex(/^[a-zA-Z0-9][a-zA-Z0-9!#$&\-\^_.]*\/[a-zA-Z0-9][a-zA-Z0-9!#$&\-\^_.]*$/);

    const validation = mimeSchema.safeParse(mimeType);
    if (!validation.success) {
      throw new Error('Invalid MIME type format');
    }

    if (!allowedTypes.includes(validation.data)) {
      throw new Error(`MIME type ${validation.data} not allowed`);
    }

    return validation.data;
  }

  // Sanitize translation text to prevent prompt injection
  static sanitizeTranslationText(text: string): string {
    if (typeof text !== 'string') {
      throw new Error('Translation text must be a string');
    }

    // Remove potential prompt injection patterns
    const dangerous = [
      /ignore\s+previous\s+instructions?/gi,
      /system\s*:/gi,
      /assistant\s*:/gi,
      /human\s*:/gi,
      /<\s*script\s*>/gi,
      /javascript\s*:/gi,
      /data\s*:/gi,
      /vbscript\s*:/gi
    ];

    let sanitized = text;
    dangerous.forEach(pattern => {
      sanitized = sanitized.replace(pattern, '[REMOVED]');
    });

    // Limit text length to prevent DoS
    if (sanitized.length > 10000) {
      throw new Error('Text too long for translation');
    }

    return this.sanitizeText(sanitized);
  }

  // Validate UUID format
  static validateUUID(uuid: string): string {
    const uuidSchema = z.string().uuid();
    const validation = uuidSchema.safeParse(uuid);

    if (!validation.success) {
      throw new Error('Invalid UUID format');
    }

    return validation.data;
  }

  // Validate API endpoint parameters
  static validateApiParams(params: Record<string, any>): Record<string, any> {
    const sanitized: Record<string, any> = {};

    for (const [key, value] of Object.entries(params)) {
      // Sanitize parameter names
      const cleanKey = key.replace(/[^a-zA-Z0-9_]/g, '');
      if (cleanKey.length === 0) continue;

      // Sanitize values based on type
      if (typeof value === 'string') {
        sanitized[cleanKey] = this.sanitizeText(value);
      } else if (typeof value === 'number' && Number.isFinite(value)) {
        sanitized[cleanKey] = value;
      } else if (typeof value === 'boolean') {
        sanitized[cleanKey] = value;
      }
      // Skip other types for security
    }

    return sanitized;
  }
}

// Rate limiting to prevent abuse
export class RateLimiter {
  private static attempts = new Map<string, { count: number; resetTime: number }>();

  static checkRateLimit(identifier: string, maxAttempts = 10, windowMs = 60000): boolean {
    const now = Date.now();
    const current = this.attempts.get(identifier);

    if (!current || now > current.resetTime) {
      this.attempts.set(identifier, { count: 1, resetTime: now + windowMs });
      return true;
    }

    if (current.count >= maxAttempts) {
      return false;
    }

    current.count++;
    return true;
  }

  static getRemainingAttempts(identifier: string, maxAttempts = 10): number {
    const current = this.attempts.get(identifier);
    if (!current || Date.now() > current.resetTime) {
      return maxAttempts;
    }
    return Math.max(0, maxAttempts - current.count);
  }
}

// Principle of Least Privilege (PoLP) implementation
import { z } from 'zod';

export enum Permission {
  // File operations
  FILE_UPLOAD = 'file:upload',
  FILE_READ = 'file:read',
  FILE_DELETE = 'file:delete',

  // Translation operations  
  TRANSLATION_CREATE = 'translation:create',
  TRANSLATION_READ = 'translation:read',
  TRANSLATION_CANCEL = 'translation:cancel',

  // Job operations
  JOB_READ_OWN = 'job:read:own',
  JOB_CREATE = 'job:create',
  JOB_CANCEL_OWN = 'job:cancel:own',

  // Admin operations (future)
  ADMIN_VIEW_ALL_JOBS = 'admin:jobs:view_all',
  ADMIN_MANAGE_USERS = 'admin:users:manage'
}

export enum UserRole {
  ANONYMOUS = 'anonymous',
  AUTHENTICATED = 'authenticated', 
  PREMIUM = 'premium',
  ADMIN = 'admin'
}

// Role-based permission matrix
const ROLE_PERMISSIONS: Record<UserRole, Permission[]> = {
  [UserRole.ANONYMOUS]: [
    Permission.FILE_UPLOAD,
    Permission.FILE_READ,
    Permission.TRANSLATION_CREATE,
    Permission.TRANSLATION_READ,
    Permission.JOB_READ_OWN,
    Permission.JOB_CREATE
  ],

  [UserRole.AUTHENTICATED]: [
    ...ROLE_PERMISSIONS[UserRole.ANONYMOUS],
    Permission.FILE_DELETE,
    Permission.JOB_CANCEL_OWN
  ],

  [UserRole.PREMIUM]: [
    ...ROLE_PERMISSIONS[UserRole.AUTHENTICATED],
    Permission.TRANSLATION_CANCEL
  ],

  [UserRole.ADMIN]: [
    ...Object.values(Permission)
  ]
};

export class PermissionManager {
  static getUserRole(user: any): UserRole {
    if (!user) return UserRole.ANONYMOUS;

    // Check user metadata for role
    const role = user.user_metadata?.role || user.app_metadata?.role;

    if (role === 'admin') return UserRole.ADMIN;
    if (role === 'premium') return UserRole.PREMIUM;
    if (user.id) return UserRole.AUTHENTICATED;

    return UserRole.ANONYMOUS;
  }

  static hasPermission(userRole: UserRole, permission: Permission): boolean {
    const rolePermissions = ROLE_PERMISSIONS[userRole] || [];
    return rolePermissions.includes(permission);
  }

  static checkPermission(user: any, permission: Permission): boolean {
    const role = this.getUserRole(user);
    return this.hasPermission(role, permission);
  }

  static enforcePermission(user: any, permission: Permission): void {
    if (!this.checkPermission(user, permission)) {
      const role = this.getUserRole(user);
      throw new Error(`Access denied. Role '${role}' lacks permission '${permission}'`);
    }
  }

  // Resource-specific permission checks
  static canAccessResource(user: any, resourceOwnerId: string, permission: Permission): boolean {
    // Users can access their own resources
    if (user?.id === resourceOwnerId) {
      return this.checkPermission(user, permission);
    }

    // Admins can access all resources
    const role = this.getUserRole(user);
    if (role === UserRole.ADMIN) {
      return this.hasPermission(role, permission);
    }

    return false;
  }

  // Rate limiting based on user role
  static getRateLimitForRole(userRole: UserRole): { maxRequests: number; windowMs: number } {
    switch (userRole) {
      case UserRole.ANONYMOUS:
        return { maxRequests: 10, windowMs: 60000 }; // 10 requests per minute

      case UserRole.AUTHENTICATED:
        return { maxRequests: 50, windowMs: 60000 }; // 50 requests per minute

      case UserRole.PREMIUM:
        return { maxRequests: 200, windowMs: 60000 }; // 200 requests per minute

      case UserRole.ADMIN:
        return { maxRequests: 1000, windowMs: 60000 }; // 1000 requests per minute

      default:
        return { maxRequests: 5, windowMs: 60000 }; // Very restrictive default
    }
  }

  // File size limits based on user role
  static getFileSizeLimitForRole(userRole: UserRole): number {
    switch (userRole) {
      case UserRole.ANONYMOUS:
        return 5 * 1024 * 1024; // 5MB

      case UserRole.AUTHENTICATED:
        return 10 * 1024 * 1024; // 10MB

      case UserRole.PREMIUM:
        return 50 * 1024 * 1024; // 50MB

      case UserRole.ADMIN:
        return 100 * 1024 * 1024; // 100MB

      default:
        return 1 * 1024 * 1024; // 1MB default
    }
  }

  // Maximum concurrent jobs based on user role
  static getMaxConcurrentJobs(userRole: UserRole): number {
    switch (userRole) {
      case UserRole.ANONYMOUS:
        return 1;

